diff --git a/tests/mobile_controls_probe.mjs b/tests/mobile_controls_probe.mjs
new file mode 100644
index 0000000..a5607ea
--- /dev/null
+++ b/tests/mobile_controls_probe.mjs
@@ -0,0 +1,346 @@
+import {mkdtemp, mkdir, readFile, writeFile} from 'node:fs/promises';
+import {spawn, spawnSync} from 'node:child_process';
+import {once} from 'node:events';
+import {tmpdir} from 'node:os';
+import {join} from 'node:path';
+import {chromium} from '/opt/mobile-test/node_modules/playwright-core/index.mjs';
+
+const ROOT='/app';
+const ARTIFACTS='/logs/verifier/artifacts';
+const EXPECTED=[
+  {name:'compact-portrait',width:390,height:844,orientation:'portrait'},
+  {name:'compact-landscape',width:844,height:390,orientation:'landscape'},
+  {name:'large-portrait',width:430,height:932,orientation:'portrait'},
+  {name:'large-landscape',width:932,height:430,orientation:'landscape'},
+  {name:'android-portrait',width:412,height:915,orientation:'portrait'},
+  {name:'android-landscape',width:915,height:412,orientation:'landscape'},
+];
+const MIN_PRACTICAL_TOUCH_SIDE=32;
+const MAX_CONTROL_COVERAGE=.35;
+const FOCUS_ZONE={x:.3,y:.325,width:.4,height:.35};
+const report={manifest:{errors:[],viewports:[]},rendered:{errors:[],viewports:[]},playability:{errors:[],viewports:[]},rotation:{errors:[]},desktop:{errors:[]},artifacts:{screenshots:[],video:null,videoError:null}};
+await mkdir(ARTIFACTS,{recursive:true});
+
+const semantic=control=>`${control.id??''} ${control.label??''} ${control.gameAction??''}`.toLowerCase();
+const rolePatterns={
+  joystick:[/joystick/,/\bmove\b/,/pitch.*roll/,/roll.*pitch/,/space.*control.*keyq.*keye/],
+  fire:[/\bfire\b/,/\bkeyf\b/,/key\s*f\b/],
+  yawLeft:[/yaw[^a-z0-9]*left/,/\bkeya\b/,/key\s*a\b/],
+  yawRight:[/yaw[^a-z0-9]*right/,/\bkeyd\b/,/key\s*d\b/],
+  collectiveDown:[/collective[^a-z0-9]*(down|lower|decrease|-)/,/\bkeys\b/,/key\s*s\b/],
+  collectiveUp:[/collective[^a-z0-9]*(up|raise|increase|\+)/,/\bkeyw\b/,/key\s*w\b/],
+  view:[/\bview\b/,/camera/,/\bkeyc\b/,/key\s*c\b/],
+  reset:[/\breset\b/,/restart/,/\bkeyr\b/,/key\s*r\b/],
+  pause:[/\bpause\b/,/\bescape\b/,/\besc\b/],
+};
+function rolesFor(controls){
+  const roles={};
+  for(const [role,patterns] of Object.entries(rolePatterns))roles[role]=controls.find(control=>patterns.some(pattern=>pattern.test(semantic(control))));
+  return roles;
+}
+const finite=value=>typeof value==='number'&&Number.isFinite(value);
+const intersects=(a,b)=>a.x<b.x+b.width&&a.x+a.width>b.x&&a.y<b.y+b.height&&a.y+a.height>b.y;
+
+let manifest={version:null,viewports:[]};
+try{manifest=JSON.parse(await readFile(join(ROOT,'mobile-controls.json'),'utf8'));}
+catch(error){report.manifest.errors.push(`mobile-controls.json: ${error.message}`);}
+if(manifest.version!==1)report.manifest.errors.push('manifest version must be 1');
+if(!Array.isArray(manifest.viewports)){
+  report.manifest.errors.push('manifest viewports must be an array');
+  manifest.viewports=[];
+}
+const byName=new Map(manifest.viewports.map(viewport=>[viewport?.name,viewport]));
+if(byName.size!==manifest.viewports.length)report.manifest.errors.push('manifest viewport names must be unique');
+const expectedNames=new Set(EXPECTED.map(viewport=>viewport.name));
+for(const viewport of manifest.viewports)if(!expectedNames.has(viewport?.name))report.manifest.errors.push(`unexpected viewport ${String(viewport?.name)}`);
+let commonIds=null;
+for(const expected of EXPECTED){
+  const errors=[];
+  const viewport=byName.get(expected.name);
+  if(!viewport){errors.push('missing viewport');report.manifest.viewports.push({name:expected.name,errors});continue;}
+  for(const field of ['width','height','orientation'])if(viewport[field]!==expected[field])errors.push(`${field} must be ${expected[field]}`);
+  const controls=Array.isArray(viewport.controls)?viewport.controls:[];
+  if(!Array.isArray(viewport.controls))errors.push('controls must be an array');
+  if(controls.length<2)errors.push('at least a joystick and action controls are required');
+  const ids=controls.map(control=>control?.id);
+  if(ids.some(id=>typeof id!=='string'||!id))errors.push('every control needs a non-empty id');
+  if(new Set(ids).size!==ids.length)errors.push('control ids must be unique');
+  const idSet=[...new Set(ids)].sort();
+  if(commonIds===null)commonIds=idSet;
+  else if(JSON.stringify(commonIds)!==JSON.stringify(idSet))errors.push('control ids differ from the other viewports');
+  for(const control of controls){
+    if(typeof control?.label!=='string'||!control.label)errors.push(`${String(control?.id)} needs a label`);
+    if(typeof control?.gameAction!=='string'||!control.gameAction)errors.push(`${String(control?.id)} needs a gameAction`);
+    const rect=control?.rect;
+    if(!rect||!['x','y','width','height'].every(key=>finite(rect[key])&&Number.isInteger(rect[key]))){errors.push(`${String(control?.id)} rect must contain integer CSS pixels`);continue;}
+    if(rect.width<MIN_PRACTICAL_TOUCH_SIDE||rect.height<MIN_PRACTICAL_TOUCH_SIDE)errors.push(`${control.id} is too small to be a practical touch target`);
+    if(rect.x<0||rect.y<0||rect.x+rect.width>expected.width||rect.y+rect.height>expected.height)errors.push(`${control.id} extends outside the viewport`);
+  }
+  for(let first=0;first<controls.length;first++)for(let second=first+1;second<controls.length;second++){
+    const a=controls[first]?.rect,b=controls[second]?.rect;
+    if(a&&b&&intersects(a,b))errors.push(`${controls[first].id} and ${controls[second].id} overlap`);
+  }
+  const central={x:expected.width*FOCUS_ZONE.x,y:expected.height*FOCUS_ZONE.y,width:expected.width*FOCUS_ZONE.width,height:expected.height*FOCUS_ZONE.height};
+  for(const control of controls)if(control?.rect&&intersects(control.rect,central))errors.push(`${control.id} obscures the central gameplay focus`);
+  const coverage=controls.reduce((sum,control)=>sum+(control?.rect?.width??0)*(control?.rect?.height??0),0)/(expected.width*expected.height);
+  if(coverage>MAX_CONTROL_COVERAGE)errors.push(`controls cover an excessive share of the viewport (${(coverage*100).toFixed(2)}%)`);
+  const roles=rolesFor(controls);
+  for(const [role,control] of Object.entries(roles))if(!control)errors.push(`missing ${role} control`);
+  const assignedRoles=Object.values(roles).filter(Boolean);
+  if(new Set(assignedRoles.map(control=>control.id)).size!==assignedRoles.length)errors.push('each gameplay role must use a distinct control');
+  const joystick=roles.joystick;
+  if(joystick?.rect){
+    const centerX=joystick.rect.x+joystick.rect.width/2;
+    if(centerX>expected.width/2)errors.push('joystick is not on the left side');
+  }
+  const actions=controls.filter(control=>control!==joystick&&control?.rect);
+  for(const control of actions){
+    const centerX=control.rect.x+control.rect.width/2;
+    if(centerX<expected.width/2)errors.push(`${control.id} is not on the right side`);
+  }
+  report.manifest.viewports.push({name:expected.name,errors,coverage});
+  report.manifest.errors.push(...errors.map(error=>`${expected.name}: ${error}`));
+}
+
+const server=spawn(process.execPath,['server.mjs'],{cwd:ROOT,stdio:['ignore','pipe','pipe']});
+let serverLog='';
+server.stdout.on('data',chunk=>{serverLog=(serverLog+chunk).slice(-12000);});
+server.stderr.on('data',chunk=>{serverLog=(serverLog+chunk).slice(-12000);});
+async function waitForServer(){
+  for(let attempt=0;attempt<100;attempt++){
+    if(server.exitCode!==null)throw new Error(`server exited ${server.exitCode}: ${serverLog}`);
+    try{const response=await fetch('http://127.0.0.1:5173/');if(response.ok)return;}catch{}
+    await new Promise(resolve=>setTimeout(resolve,100));
+  }
+  throw new Error(`server did not become ready: ${serverLog}`);
+}
+await waitForServer();
+const browser=await chromium.launch({headless:true,executablePath:process.env.CHROME_BIN||'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage','--use-gl=angle','--use-angle=swiftshader']});
+const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
+const touchPoint=(id,x,y)=>({id,x,y,radiusX:5,radiusY:5,force:1});
+const idSelector=id=>`[id=${JSON.stringify(id)}]`;
+async function dispatchTouch(session,type,points){await session.send('Input.dispatchTouchEvent',{type,touchPoints:points});}
+async function rectFor(page,control){
+  if(!control)return null;
+  const locator=page.locator(idSelector(control.id));
+  if(await locator.count()!==1)return null;
+  return locator.boundingBox();
+}
+async function tapControl(page,control){
+  const rect=await rectFor(page,control);if(!rect)return false;
+  await page.touchscreen.tap(rect.x+rect.width/2,rect.y+rect.height/2);return true;
+}
+async function holdControl(page,session,control,duration=180,id=1){
+  const rect=await rectFor(page,control);if(!rect)return false;
+  await dispatchTouch(session,'touchStart',[touchPoint(id,rect.x+rect.width/2,rect.y+rect.height/2)]);
+  await pause(duration);await dispatchTouch(session,'touchEnd',[]);await pause(45);return true;
+}
+async function moveJoystick(page,session,control,xRatio,yRatio,duration=170,id=1){
+  const rect=await rectFor(page,control);if(!rect)return false;
+  const center={x:rect.x+rect.width/2,y:rect.y+rect.height/2};
+  const target={x:center.x+xRatio*rect.width*.42,y:center.y+yRatio*rect.height*.42};
+  await dispatchTouch(session,'touchStart',[touchPoint(id,center.x,center.y)]);
+  await dispatchTouch(session,'touchMove',[touchPoint(id,target.x,target.y)]);
+  await pause(duration);await dispatchTouch(session,'touchEnd',[]);await pause(45);return true;
+}
+async function startByTouch(page,width,height){
+  if(await page.locator('#setup-dialog[open]').count()){
+    if(await page.locator('#fly').count())await page.locator('#fly').tap();
+  }else await page.touchscreen.tap(width/2,height/2);
+  try{await page.waitForFunction(()=>document.body.classList.contains('flying'),null,{timeout:10000});return true;}catch{return false;}
+}
+function activeCodes(events){
+  const active=new Set();
+  for(const event of events){if(event.type==='down')active.add(event.code);else if(event.type==='up')active.delete(event.code);}
+  return [...active];
+}
+function axisCoverage(events){
+  const codes=new Set(events.filter(event=>event.type==='down').map(event=>event.code));
+  return {
+    pitchPositive:codes.has('Space'),pitchNegative:codes.has('ControlLeft')||codes.has('ControlRight'),
+    rollPositive:codes.has('KeyE'),rollNegative:codes.has('KeyQ'),
+    yawPositive:codes.has('KeyD'),yawNegative:codes.has('KeyA'),
+    collectivePositive:codes.has('KeyW'),collectiveNegative:codes.has('KeyS'),
+  };
+}
+async function newTouchPage(expected){
+  const context=await browser.newContext({viewport:{width:expected.width,height:expected.height},hasTouch:true,isMobile:true,deviceScaleFactor:1});
+  const page=await context.newPage();
+  await page.addInitScript(()=>{
+    Object.defineProperty(window,'__mobileProbeEvents',{value:[],writable:false,configurable:false});
+    addEventListener('keydown',event=>window.__mobileProbeEvents.push({type:'down',code:event.code,repeat:event.repeat}),true);
+    addEventListener('keyup',event=>window.__mobileProbeEvents.push({type:'up',code:event.code,repeat:event.repeat}),true);
+  });
+  const errors=[];
+  page.on('pageerror',error=>errors.push(error.message));
+  page.on('console',message=>{if(message.type()==='error')errors.push(message.text());});
+  await page.goto('http://127.0.0.1:5173/',{waitUntil:'networkidle'});
+  return {context,page,errors};
+}
+
+for(const expected of EXPECTED){
+  const viewport=byName.get(expected.name),controls=Array.isArray(viewport?.controls)?viewport.controls:[];
+  const roles=rolesFor(controls),renderErrors=[];
+  if(!viewport)renderErrors.push('manifest viewport is missing');
+  if(controls.length<2)renderErrors.push('manifest does not identify the rendered controls');
+  const {context,page,errors:pageErrors}=await newTouchPage(expected);
+  const measurements=[];
+  for(const control of controls){
+    const locator=page.locator(idSelector(control.id));
+    if(await locator.count()!==1){renderErrors.push(`${control.id} is missing or duplicated`);continue;}
+    if(!(await locator.isVisible()))renderErrors.push(`${control.id} is not visible`);
+    const box=await locator.boundingBox();
+    if(!box){renderErrors.push(`${control.id} has no rendered box`);continue;}
+    measurements.push({id:control.id,...box});
+    for(const key of ['x','y','width','height'])if(Math.abs(box[key]-control.rect[key])>2)renderErrors.push(`${control.id}.${key} differs from manifest by more than 2px`);
+    const touchAction=await locator.evaluate(element=>getComputedStyle(element).touchAction);
+    if(touchAction!=='none')renderErrors.push(`${control.id} touch-action is ${touchAction}`);
+  }
+  for(const box of measurements){
+    if(box.width<MIN_PRACTICAL_TOUCH_SIDE||box.height<MIN_PRACTICAL_TOUCH_SIDE)renderErrors.push(`${box.id} renders too small to be a practical touch target`);
+    if(box.x<0||box.y<0||box.x+box.width>expected.width||box.y+box.height>expected.height)renderErrors.push(`${box.id} renders outside the viewport`);
+  }
+  for(let first=0;first<measurements.length;first++)for(let second=first+1;second<measurements.length;second++)if(intersects(measurements[first],measurements[second]))renderErrors.push(`${measurements[first].id} and ${measurements[second].id} overlap when rendered`);
+  const renderedCentral={x:expected.width*FOCUS_ZONE.x,y:expected.height*FOCUS_ZONE.y,width:expected.width*FOCUS_ZONE.width,height:expected.height*FOCUS_ZONE.height};
+  for(const box of measurements)if(intersects(box,renderedCentral))renderErrors.push(`${box.id} renders over the central gameplay focus`);
+  const renderedCoverage=measurements.reduce((sum,box)=>sum+box.width*box.height,0)/(expected.width*expected.height);
+  if(renderedCoverage>MAX_CONTROL_COVERAGE)renderErrors.push(`rendered controls cover an excessive share of the viewport (${(renderedCoverage*100).toFixed(2)}%)`);
+  const boxesById=new Map(measurements.map(box=>[box.id,box]));
+  const joystickBox=roles.joystick&&boxesById.get(roles.joystick.id);
+  if(joystickBox){
+    const centerX=joystickBox.x+joystickBox.width/2;
+    if(centerX>expected.width/2)renderErrors.push('joystick does not render on the left side');
+  }
+  const renderedActions=controls.filter(control=>control!==roles.joystick).map(control=>({control,box:boxesById.get(control.id)})).filter(item=>item.box);
+  for(const {control,box} of renderedActions){
+    const centerX=box.x+box.width/2;
+    if(centerX<expected.width/2)renderErrors.push(`${control.id} does not render on the right side`);
+  }
+  const scroll=await page.evaluate(()=>({width:document.documentElement.scrollWidth,height:document.documentElement.scrollHeight,innerWidth,innerHeight}));
+  const hudOverlaps=await page.evaluate(ids=>{
+    const controls=ids.map(id=>document.getElementById(id)).filter(Boolean);
+    const hud=[document.querySelector('.nav'),document.querySelector('footer'),document.querySelector('.mission-live:not([hidden])'),document.querySelector('#notification.show'),document.querySelector('.menu-toggle')].filter(element=>element&&getComputedStyle(element).display!=='none'&&element.getClientRects().length);
+    const overlaps=(a,b)=>a.left<b.right&&a.right>b.left&&a.top<b.bottom&&a.bottom>b.top;
+    return controls.flatMap(control=>hud.filter(item=>overlaps(control.getBoundingClientRect(),item.getBoundingClientRect())).map(item=>`${control.id}:${item.id||item.className||item.tagName}`));
+  },controls.map(control=>control.id));
+  if(hudOverlaps.length)renderErrors.push(...hudOverlaps.map(value=>`HUD overlap ${value}`));
+  if(scroll.width>scroll.innerWidth+1||scroll.height>scroll.innerHeight+1)renderErrors.push(`page overflows ${scroll.width}x${scroll.height} in a ${scroll.innerWidth}x${scroll.innerHeight} viewport`);
+  if(pageErrors.length)renderErrors.push(...pageErrors.map(error=>`browser error: ${error}`));
+  const screenshot=join(ARTIFACTS,`${expected.name}.png`);await page.screenshot({path:screenshot});report.artifacts.screenshots.push(screenshot);
+  report.rendered.viewports.push({name:expected.name,errors:renderErrors,measurements,hudOverlaps});
+  report.rendered.errors.push(...renderErrors.map(error=>`${expected.name}: ${error}`));
+
+  const dynamic={name:expected.name,errors:[],started:false,axisCoverage:{},viewChanged:false,resetWorked:false,pauseWorked:false,resumed:false,fireWorked:false,multiTouch:false,noStuck:false,keyEvents:[]};
+  for(const [role,control] of Object.entries(roles))if(!control)dynamic.errors.push(`missing ${role} control`);
+  if(!dynamic.errors.length){
+    dynamic.started=await startByTouch(page,expected.width,expected.height);
+    if(!dynamic.started)dynamic.errors.push('touch did not start the game');
+    const session=await context.newCDPSession(page);
+    if(dynamic.started){
+      await moveJoystick(page,session,roles.joystick,-1,0);
+      await moveJoystick(page,session,roles.joystick,1,0);
+      await moveJoystick(page,session,roles.joystick,0,-1);
+      await moveJoystick(page,session,roles.joystick,0,1);
